     * b's left child], d(B) right leaf. Deleting "d" makes x=NULL,
     * x_parent=c, sibling w=b black with far nephew a red --
     * delete_fixup Case 4 (right/mirror). */
    const rb_op ops[] = {
        {'i', "c", 0}, {'i', "d", 0}, {'i', "b", 0}, {'i', "a", 0},
